import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"业务配置：微信、短信与存储","description":"","frontmatter":{},"headers":[],"relativePath":"features/business-config.md","filePath":"features/business-config.md"}'),c={name:"features/business-config.md"};function i(r,e,d,n,l,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="业务配置-微信、短信与存储" tabindex="-1">业务配置：微信、短信与存储 <a class="header-anchor" href="#业务配置-微信、短信与存储" aria-label="Permalink to &quot;业务配置：微信、短信与存储&quot;">​</a></h1><p>入口为 <strong>系统管理 → 系统业务配置</strong>，地址 <code>/system/business-config</code>。单页包含微信、短信、OSS三个独立分区；每个分区独立加载、保存和报告失败。旧微信配置深链由前端 redirect 转到当前微信分区。</p><h2 id="身份与前置" tabindex="-1">身份与前置 <a class="header-anchor" href="#身份与前置" aria-label="Permalink to &quot;身份与前置&quot;">​</a></h2><p>平台身份配合 <code>system:businessConfig:query/edit</code>。仅查询身份可以读取和重试，不能保存。数据库密钥能力要求部署者设置稳定的 <code>CONFIG_MASTER_KEY</code>：Base64编码的恰好32随机字节；不在前端配置或文档中填真实值。</p><table tabindex="0"><thead><tr><th>分区</th><th>parameters</th><th>写入型 secrets</th></tr></thead><tbody><tr><td>wechat</td><td>clientId、callbackUri、credentialMode、secretEnvName</td><td>appSecret</td></tr><tr><td>sms</td><td>provider、signature、templateId、region、sdkAppId</td><td>accessKeyId、accessKeySecret</td></tr><tr><td>oss</td><td>provider、endpoint、bucket、basePath</td><td>accessKey、secretKey</td></tr></tbody></table><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>滚动到要维护的微信、短信或存储区域，确认当前生效说明与密钥“已配置”标记；读取不返回密钥明文。技术响应中的source/effectiveState/encryptionReady用于解释配置来源、状态和加密能力。</li><li>修改公开参数及 enabled。留空密钥输入表示保留原配置，明确勾选清除才进入 <code>clearSecrets</code>。</li><li>点击该区域“保存微信网站授权”“保存短信服务”或“保存对象存储”，以该分区原revision提交；不要拿其他分区的revision，也不要把保存一个区域理解为保存全部区域。</li><li>成功后读回公开参数与状态。失败时保留输入，针对分区重试；并发冲突先重新读取，再合并自己的修改。</li></ol><p>例如维护短信参数时，选择区域中的“供应商”，填写已获授权的“短信签名”和“模板编号”，保持“启用”关闭，仅保存该区域；重新读取后公开参数应一致，微信和存储输入不会被该操作提交。没有真实供应商资质时不点击发送，也不据保存成功声称短信已送达。</p><p><code>GET/PUT /system/businessConfig/{section}</code> 使用上述 section。PUT body为 <code>enabled, parameters, secrets, clearSecrets, revision</code>；GET返回 <code>secretsConfigured</code>布尔映射，没有 secrets值。</p><h2 id="实际能力边界" tabindex="-1">实际能力边界 <a class="header-anchor" href="#实际能力边界" aria-label="Permalink to &quot;实际能力边界&quot;">​</a></h2><p>微信是 <strong>PC网站授权</strong>，不是公众号、小程序或完整扫码登录。当前只有网站授权发起/state验证；回调账号绑定、扫码登录及绑定管理尚未交付，没有真实网站应用资质时实际扫码验证暂缓。显示配置就绪不能当作第三方身份已验证。短信适配阿里云/腾讯云，<code>ADAPTED_SEND_UNVERIFIED</code>不表示真实发送成功。存储运行时目前支持MinIO；启用保存会校验连接与桶，失败保留原配置，历史文件继续依据原平台版本读取。</p><p>首次保存前允许沿用显式部署存储配置；保存后的数据库enabled/revision决定当前运行配置。不能每次启动重生成主密钥，否则历史密文无法解密。恢复和备份规则见<a href="/xinghui-admin-vue3/docs/operations/security.html">安全运维</a>。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/views/system/business-config/index.vue</code>、<code>apps/web-ele/src/api/system/business-config.ts</code>、<code>apps/web-ele/src/router/routes/legacy-wechat.ts</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/businessconfig/BusinessConfigService.java</code>（<code>PARAMETERS</code>、<code>SECRET_FIELDS</code>、<code>Change/View</code>）。</li><li>加密：<code>common/common-core/src/main/java/com/xinghuiTec/config/SecretCipher.java</code>；存储：<code>common/common-oss/src/main/java/com/xinghuiTec/oss/config/OssRuntimeSettings.java</code>。</li></ul>',14)])])}const p=t(c,[["render",i]]);export{m as __pageData,p as default};
